-- ============================================================================
-- Interclasses IOP -- elegibilidade dos alunos (regra de notas vermelhas)
-- Rode no SQL Editor do Supabase (https://supabase.com/dashboard).
--
-- Regra: aluno so pode jogar com, no maximo, 1 nota vermelha (< 7,0) apos
-- a Recuperacao 1o Semestre substituir a nota da disciplina reprovada no
-- 2o bimestre. Com 2+ notas vermelhas -> sugerido para corte.
--
-- Os dados abaixo foram extraidos manualmente dos 48 PDFs do SIMAED
-- (24 turmas x Relacao de Notas do 2o Bimestre + 24 x Recuperacao 1o
-- Semestre), cruzados com o cadastro oficial de alunos (aluno_id, quando
-- encontrado). Nao ha lancamento de notas por disciplina dentro deste app
-- ainda -- por isso esta tabela funciona como um "instantaneo" que precisa
-- ser reimportado a cada bimestre/recuperacao (basta rodar de novo o bloco
-- de INSERT com os dados atualizados; o ON CONFLICT atualiza quem ja existe).
-- ============================================================================

create table if not exists interclasses_elegibilidade (
  id uuid primary key default gen_random_uuid(),
  edicao text not null default '2026',
  aluno_id uuid references alunos(id) on delete set null,
  nome text not null,
  turma_id text not null,
  numero_chamada integer,
  status text not null check (status in ('apto','atencao','inapto','transferido','remanejado')),
  notas_vermelhas_bimestre integer not null default 0,
  notas_vermelhas_final integer not null default 0,
  situacao text,
  data_situacao text,
  atualizado_em timestamptz not null default now()
);

create unique index if not exists interclasses_elegibilidade_turma_chamada_uk
  on interclasses_elegibilidade (edicao, turma_id, numero_chamada);

create index if not exists interclasses_elegibilidade_aluno_idx
  on interclasses_elegibilidade (aluno_id);

alter table interclasses_elegibilidade enable row level security;

-- So o professor logado ve/edita -- e um dado sensivel (sugestao de corte),
-- nao faz parte do link publico de autoinscricao.
drop policy if exists interclasses_elegibilidade_all on interclasses_elegibilidade;
create policy interclasses_elegibilidade_all on interclasses_elegibilidade
  for all to authenticated
  using (true) with check (true);

-- ----------------------------------------------------------------------------
-- Import/atualizacao dos dados (2o Bimestre + Recuperacao 1o Semestre 2026)
-- ----------------------------------------------------------------------------
on conflict (edicao, turma_id, numero_chamada) do update set
  aluno_id = excluded.aluno_id,
  nome = excluded.nome,
  status = excluded.status,
  notas_vermelhas_bimestre = excluded.notas_vermelhas_bimestre,
  notas_vermelhas_final = excluded.notas_vermelhas_final,
  situacao = excluded.situacao,
  data_situacao = excluded.data_situacao,
  atualizado_em = now();
